def overlap(a, b):
    A, B = set(a), set(b)
    return len(A & B) / max(1, len(A | B))
r1, r2 = ['d1', 'd2', 'd3'], ['d2', 'd3', 'd4']
print('branch overlap:', round(overlap(r1, r2), 2), '-> MERGE' if overlap(r1, r2) > 0.5 else '-> keep separate')

